import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const g = load(process.argv[2]);
const air = (x,y,z) => g.blockAt(x,y,z).replace("minecraft:","") === "air";
const solid = (x,y,z) => !air(x,y,z);
const stand = (x,y,z) => solid(x,y-1,z) && air(x,y,z) && air(x,y+1,z);
const inBox = (x,y,z) => x>=1&&x<=12&&z>=7&&z<=22&&y>=14&&y<=16;
const start = [6,14,22];
const seen = new Set([start.join()]); const q=[start]; 
while (q.length) { const [x,y,z]=q.shift(); for (const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]) for (const dy of [0,1,-1]) {
  const nx=x+dx, nz=z+dz, ny=y+dy; if (!inBox(nx,ny,nz)) continue; if (!stand(nx,ny,nz)) continue; const k=[nx,ny,nz].join(); if (seen.has(k)) continue; seen.add(k); q.push([nx,ny,nz]); } }
let total=0; const unreached=[];
for (let x=1;x<=12;x++) for (let z=7;z<=22;z++) if (stand(x,14,z)) { total++; if (!seen.has([x,14,z].join())) unreached.push([x,z]); }
console.log("standable", total, "reached", seen.size, "unreached", JSON.stringify(unreached));
// furniture check: each non-air block in box at y14 with a reachable neighbour
const targets=[];
for (let x=1;x<=12;x++) for (let z=7;z<=22;z++) if (solid(x,14,z)) { const nb=[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dz])=>seen.has([x+dx,14,z+dz].join())); if (!nb) targets.push([x,z,g.blockAt(x,14,z)]); }
console.log("furniture at y14 with no reachable neighbour:", JSON.stringify(targets));
EOF
